#define R3D(a,A) mix(A*dot(p,A),p,cos(a)) + sin(a)*cross(p,A)
#define R2D(a) mat2( cos( a + vec4(0,11,33,0 )))

void mainImage( out vec4 o, in vec2 FC )
{
float i,j,d=.4,e,t=iTime;
vec3 p,q,r=iResolution;
o=vec4(0.);

for(i=0.;i++<64.&&d>1e-4;){
    p=vec3((FC.xy-.5*r.xy)/r.y,e);
    p.z-=4.;
    //p*=R3D(t,p);

    for(j=0.;j++<4.;)
        p.xy*=R2D(t*.5),
        p=abs(p-.04)-.05,
        d=max(min(p.y,p.z),p.x)/d,
        d-=dot(p,p)/1e4;

    e-=d;

}o=vec4(sqrt(p/d),1)*3./i;
}
